package com.mhtextractor;

import atlantafx.base.theme.NordLight;
import com.mhtextractor.config.GuiState;
import com.mhtextractor.config.GuiStateManager;
import com.mhtextractor.gui.component.NotificationHost;
import com.mhtextractor.gui.component.SidePanelHost;
import com.mhtextractor.i18n.I18n;
import javafx.application.Application;
import javafx.collections.ListChangeListener;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.layout.StackPane;
import javafx.geometry.Rectangle2D;
import javafx.stage.Screen;
import javafx.stage.Stage;
import javafx.stage.Window;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.util.Locale;
import java.util.Objects;

@Slf4j
public class App extends Application {

    private static String customCssUrl;

    @Override
    public void start(Stage primaryStage) throws IOException {
        // 全局未捕获异常处理器 — 将异常输出到控制台和日志
        Thread.currentThread().setUncaughtExceptionHandler((t, e) -> {
            log.error(I18n.msg("log.app.01", t.getName(), e.getMessage()), e);
            System.err.println("FATAL: " + e.getMessage());
            e.printStackTrace();
        });

        // 会话 13（i18n）：locale 必须在 FXMLLoader.load() 之前就绪——FXML 的 %key 解析发生在 load 期间
        GuiState guiState = GuiStateManager.load();
        if (guiState != null && guiState.getLocale() != null && !guiState.getLocale().isBlank()) {
            Locale locale = I18n.parseLocale(guiState.getLocale());
            if (locale != null) {
                I18n.setLocale(locale);
            }
        }

        FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/mhtextractor/gui/view/MainView.fxml"));
        // P6-B：控制器要拿"FXML 命名空间"（fx:id → MainViewRefs）来取代 42 个 @FXML 节点字段，
        // 而 namespace 只有 loader 有 —— controller factory 是把它交给控制器的入口（缺这根线就是
        // 指南记的"未验证"缺口）。它会覆盖 MainView.fxml 里的 fx:controller 实例化（工厂优先），
        // 但"注入 @FXML 成员 → 反射调用 initialize()"的时机与默认路径逐字相同
        // （javafx.fxml.FXMLLoader 源码 926-931 与 2555-2664 行），故 initialize() 里 namespace 已完整。
        // TestMain 里同一行是逐行等价的镜像（改一处必须改另一处）。
        loader.setControllerFactory(_ -> new com.mhtextractor.gui.controller.MainController(loader));
        loader.setResources(I18n.bundle());
        // 会话 19：场景根外包一层 StackPane，供 NotificationHost 挂"右上角 toast + 居中提醒"两层
        //（取代模态 Alert；两条图层的 z 序与鼠标穿透见 NotificationHost 的类说明）
        // ⚠️ 必须先落到 Parent 局部变量再传：直接写 new StackPane(loader.load()) 会被推断成
        //    StackPane(Node...) 变参重载（load() 推成 Node[]），运行时 ClassCastException（实测踩过）。
        Parent root = loader.load();
        // Q6a（R3.2 层序）：主界面外包一层"覆盖层"，右侧参数侧边栏是它的第二个子节点 ——
        // 覆盖层再被包成 shell，而 NotificationHost.install 把 toast/模态两层【追加】到 shell 末尾，
        // 于是"主界面 → 侧边栏 → 提醒层"由父子结构唯一决定，不依赖 shell 的子节点顺序，
        // 也不需要用（更不许用）toFront 去提权。详见 SidePanelHost 的类注释。
        StackPane overlay = SidePanelHost.install(root);
        StackPane shell = new StackPane(overlay);
        Scene scene = new Scene(shell);
        NotificationHost.install(scene, shell);
        // 控制器由 FXMLLoader 装配（生产启动器<b>不</b>持有它的引用：P7 起没有任何测试模式分支，
        // 也不再需要"把控制器交给测试侧"这条通路 —— 那道通路已移到测试源集的 gui.acceptance.TestMain）

        // 引入 AtlantaFX Nord Light 主题
        Application.setUserAgentStylesheet(new NordLight().getUserAgentStylesheet());

        // 注入自定义样式到所有窗口（包括 Dialog/Alert 创建的独立 Scene）
        customCssUrl = Objects.requireNonNull(getClass().getResource("/custom.css")).toExternalForm();
        scene.getStylesheets().add(customCssUrl);
        injectStylesToAllWindows();

        // 窗口初始大小自适应屏幕（宽度 80%：保证列表下方按钮行 7 个按钮完整显示；高度 85%）
        Rectangle2D screenBounds = Screen.getPrimary().getVisualBounds();
        double winWidth  = screenBounds.getWidth()  * 0.80;
        double winHeight = screenBounds.getHeight() * 0.85;

        primaryStage.setTitle(I18n.get("app.title"));
        primaryStage.setScene(scene);
        primaryStage.setWidth(winWidth);
        primaryStage.setHeight(winHeight);
        primaryStage.setMinWidth(900);
        primaryStage.setMinHeight(650);
        primaryStage.centerOnScreen();
        primaryStage.show();
        // 选项 B（2026-10-10 用户拍板）：P5 接线前不启动随包后端。
        // 后端当前仍带开发期约束（IpcFiles 要求 java.io.tmpdir 在 H:/TEST/temp 下、
        // 且输入/输出白名单为 H:/TEST/mht），真实环境下必然启动失败并弹"后端不可用"噪音；
        // GUI 业务也仍走进程内 app。相关类/探针/脚本保留，供 P5 生产化接线。
        var backendStatus = (javafx.scene.control.Label) scene.lookup("#backendStatusLabel");
        if (backendStatus != null) {
            backendStatus.setVisible(false);
            backendStatus.setManaged(false);
        }

        // P7（测试面收口）：本类**不再**有任何测试模式分支。
        // 演练（原 -Dagent.exit.delay）与 GUI 自动化（原 -Dtest.mode=true）都由测试源集的
        // com.mhtextractor.gui.acceptance.TestMain 承载 —— 它按与本方法逐行相同的装配起窗口，
        // 只是多一层"起完窗口后驱动 FeatureExercise"的测试外壳。生产启动代码不再读任何测试开关。
    }

    /**
     * 为所有现有和未来的窗口（含 Dialog/Alert 弹窗）注入自定义 CSS
     */
    private void injectStylesToAllWindows() {
        // 先为当前已有的所有窗口注入
        for (Window w : Window.getWindows()) {
            injectToWindow(w);
        }

        // 监听新窗口创建（Dialog/Alert 会创建新 Stage）
        Window.getWindows().addListener((ListChangeListener<Window>) c -> {
            while (c.next()) {
                if (c.wasAdded()) {
                    for (Window w : c.getAddedSubList()) {
                        injectToWindow(w);
                    }
                }
            }
        });
    }
    @SuppressWarnings("unchecked")
    private void injectToWindow(Window window) {
        if (!(window instanceof Stage stage)) return;
        Scene s = stage.getScene();
        if (s == null) {
            // 场景可能稍后设置，监听场景变化
            javafx.beans.value.ChangeListener<Scene>[] holder = new javafx.beans.value.ChangeListener[1];
            holder[0] = (_, _, newS) -> {
                if (newS != null) {
                    if (!newS.getStylesheets().contains(customCssUrl)) {
                        newS.getStylesheets().add(customCssUrl);
                    }
                    stage.sceneProperty().removeListener(holder[0]);
                }
            };
            stage.sceneProperty().addListener(holder[0]);
        } else {
            if (!s.getStylesheets().contains(customCssUrl)) {
                s.getStylesheets().add(customCssUrl);
            }
        }
    }

    public static void main(String[] args) {
        launch(args);
    }
}
package com.mhtextractor.gui.acceptance;

import atlantafx.base.theme.NordLight;
import com.mhtextractor.config.GuiState;
import com.mhtextractor.config.GuiStateManager;
import com.mhtextractor.gui.component.NotificationHost;
import com.mhtextractor.gui.component.SidePanelHost;
import com.mhtextractor.gui.component.BackendConnectionPresenter;
import com.mhtextractor.gui.controller.AgentExercise;
import com.mhtextractor.gui.controller.FeatureExercise;
import com.mhtextractor.gui.controller.MainController;
import com.mhtextractor.i18n.I18n;
import javafx.application.Application;
import javafx.application.Platform;
import javafx.fxml.FXMLLoader;
import javafx.geometry.Rectangle2D;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.layout.StackPane;
import javafx.stage.Screen;
import javafx.stage.Stage;

import java.util.Locale;
import java.util.Objects;

/**
 * GUI 自动化的<b>测试侧入口</b>（P7：把 {@code -Dtest.mode} 从生产启动代码里拿掉）。
 *
 * <h2>为什么要有这个类</h2>
 * <p>P7 之前，自动化是这样起的：{@code java ... -Dtest.mode=true com.mhtextractor.App}，
 * 由 {@code App.start()} 里的一段 {@code "true".equals(System.getProperty("test.mode"))} 分支
 * 反射调用 {@code FeatureExercise.runAutomatedTests()}。那意味着<b>生产启动器里跑着测试逻辑</b>：
 * 一个开关、一个反射挂钩、一个 {@code CONTROLLER} 字段，还有 {@code MainController} 关窗路径上
 * 第二处 {@code test.mode} 旁路。</p>
 *
 * <p>P7 把这层耦合整个搬到测试源集：本类照 {@code App.start()} 的装配顺序<b>逐行等价</b>地起同一个
 * 真窗口（{@code MainView.fxml} + 同一个 {@code MainController} + 同一套 {@code SidePanelHost} /
 * {@code NotificationHost} 接线 + 同一套 AtlantaFX 主题与 {@code custom.css}），
 * 只是在窗口起来之后再驱动测试。{@code App} 因此恢复成纯生产启动器。</p>
 *
 * <h2>两种测试模式</h2>
 * <ul>
 *   <li>{@code -Dtest.mode=true}（默认）—— GUI 自动化：延迟 2s 后在 FX 线程跑
 *       {@code FeatureExercise.runAutomatedTests()}，把结果写 {@code logs/test-results.txt}，
 *       然后 {@code Platform.exit() + System.exit(0/1)}。<b>结果文件契约不变</b>：
 *       仍是 {@code === RESULTS: N passed, M failed ===} 行（{@code run-matrix.ps1} 校验它）。</li>
 *   <li>{@code -Dagent.exit.delay=<ms>} —— 追踪演练：跑 {@code exerciseAllFeatures()}，
 *       到点自尽。原先由 {@code App} 承载（native 可达性元数据采集用），P7 一并搬到这里。</li>
 * </ul>
 *
 * <p>⚠️ 它必须与 {@code target/classes} 一起出现在 classpath 上；<b>打进生产 jar 与 native 镜像
 * 的只有 {@code App}</b>，正式发行包不含本类。</p>
 *
 * <p>⚠️ 本类与 {@code App} 的装配是<b>有意重复</b>的：{@code App} 的装配顺序本身就是被测对象的一部分
 * （{@code NotificationHost} 的层序、{@code SidePanelHost} 的覆盖层都由它决定），
 * 把这段抽成共享工具会引入"测试跑的不是生产那段代码"的疑问。改 {@code App.start()} 的装配时，
 * 必须同步改这里。</p>
 */
public final class TestMain extends Application {

    /** 起窗口之后、开始驱动断言之前的稳定等待（毫秒）——与旧 {@code App} 的 2000ms 一致。 */
    private static final long AUTOMATION_DELAY_MS = 2000;

    /** 自动化总时限（毫秒）：超时强制退出 1，绝不允许测试 harness 永久挂住。 */
    private static final long AUTOMATION_WATCHDOG_MS = 300_000;

    private static String customCssUrl;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // 与 App.start() 同：locale 必须在 FXMLLoader.load() 之前就绪
        GuiState guiState = GuiStateManager.load();
        if (guiState != null && guiState.getLocale() != null && !guiState.getLocale().isBlank()) {
            Locale locale = I18n.parseLocale(guiState.getLocale());
            if (locale != null) {
                I18n.setLocale(locale);
            }
        }

        FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/mhtextractor/gui/view/MainView.fxml"));
        // P6-B：与 App.start() 同一行（逐行等价 —— 改一处必须改另一处，见类 javadoc）。
        // 控制器由此拿到 loader，从而能在 initialize() 里用 getNamespace() 构造 MainViewRefs。
        loader.setControllerFactory(_ -> new MainController(loader));
        loader.setResources(I18n.bundle());
        Parent root = loader.load();
        StackPane overlay = SidePanelHost.install(root);
        StackPane shell = new StackPane(overlay);
        Scene scene = new Scene(shell);
        NotificationHost.install(scene, shell);
        MainController controller = loader.getController();

        Application.setUserAgentStylesheet(new NordLight().getUserAgentStylesheet());
        customCssUrl = Objects.requireNonNull(getClass().getResource("/custom.css")).toExternalForm();
        scene.getStylesheets().add(customCssUrl);

        Rectangle2D screenBounds = Screen.getPrimary().getVisualBounds();
        primaryStage.setTitle(I18n.get("app.title"));
        primaryStage.setScene(scene);
        primaryStage.setWidth(screenBounds.getWidth() * 0.80);
        primaryStage.setHeight(screenBounds.getHeight() * 0.85);
        primaryStage.setMinWidth(900);
        primaryStage.setMinHeight(650);
        primaryStage.centerOnScreen();
        primaryStage.show();
        BackendConnectionPresenter.install(primaryStage,
                (javafx.scene.control.Label) scene.lookup("#backendStatusLabel"), shell);

        String agentDelay = System.getProperty("agent.exit.delay");
        if (agentDelay != null) {
            // 步骤 6（需求 C3 / 决策 E）：演练已从 FeatureExercise 外迁至 AgentExercise，调用点随迁
            AgentExercise exercise = new AgentExercise(controller);
            exercise.exerciseAllFeatures();
            new java.util.Timer(true).schedule(new java.util.TimerTask() {
                @Override
                public void run() {
                    Platform.exit();
                    System.exit(0);
                }
            }, Long.parseLong(agentDelay));
            return;
        }

        if (!"true".equals(System.getProperty("test.mode"))) {
            // 既没给测试开关也没给演练延迟：什么都不驱动（不是 GUI 自动化的启动方式）
            System.err.println("[TestMain] neither -Dtest.mode=true nor -Dagent.exit.delay=<ms> given"
                    + " - window is up but no test will run");
            return;
        }

        // 超时保护：自动化若挂住，进程必须自己退出，不能堵住复验流水线
        Thread watchdog = new Thread(() -> {
            try {
                Thread.sleep(AUTOMATION_WATCHDOG_MS);
            } catch (InterruptedException e) {
                return;
            }
            System.err.println("[TestMain] WATCHDOG: automated tests exceeded "
                    + AUTOMATION_WATCHDOG_MS + " ms - forcing exit 1");
            Runtime.getRuntime().halt(1);
        }, "test-mode-watchdog");
        watchdog.setDaemon(true);
        watchdog.start();

        new java.util.Timer(true).schedule(new java.util.TimerTask() {
            @Override
            public void run() {
                // 自动化测试直接操作 JavaFX 控件，必须回到 FX 线程执行
                Platform.runLater(() -> {
                    boolean success = new FeatureExercise(controller).runAutomatedTests();
                    Platform.exit();
                    System.exit(success ? 0 : 1);
                });
            }
        }, AUTOMATION_DELAY_MS);
    }

    public static void main(String[] args) {
        launch(args);
    }
}
package com.mhtextractor.app;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mhtextractor.app.ipc.*;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.uiport.*;
import java.io.IOException;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import static com.mhtextractor.app.ipc.IpcCodec.*;

/** Client-side four-channel adapter. It owns the existing BackendSession, never a second transport. */
public final class IpcUiport implements Uiport, AutoCloseable {
    public record RuntimeContext(boolean imageModeEnabled, String inputFolder, String outputFolder,
                                 boolean openFolderAfterComplete) {}
    public record WorkspacePage(long revision, int total, int offset, int groupCount, List<ItemVm> items,
                                WorkspaceVm snapshot) {
        public WorkspacePage { items = List.copyOf(items); }
    }
    public record Metrics(long heapPoolPeakBytes, int callbackQueuePeak, int callbackQueueSize,
                          long activityWorkers, long rawProgress, long sentProgress) {}
    /** Typed IPC-only queries supplement the shared in-process query contract. */
    public interface Queries extends WorkspaceQueries {
        WorkspacePage workspacePage(int offset, int limit);
        IpcFilesClient.FileRef fileInfo(IpcFilesClient.FileRef ref);
        Metrics metrics();
        PortEvent.PreviewPayload previewFiles(String path);
    }

    private final ObjectMapper json = new ObjectMapper().enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
    private final ExecutorService delivery = Executors.newSingleThreadExecutor(
            Thread.ofPlatform().name("ipc-uiport-events").daemon(true).factory());
    private final ExecutorService controls = Executors.newSingleThreadExecutor(
            Thread.ofPlatform().name("ipc-uiport-controls").daemon(true).factory());
    private final Object releaseLock = new Object();
    private CompletableFuture<JsonNode> releaseTail = CompletableFuture.completedFuture(null);
    private volatile Thread deliveryThread;
    private final List<Consumer<PortEvent>> listeners = new CopyOnWriteArrayList<>();
    private final CompletableFuture<IpcFailure> failure = new CompletableFuture<>();
    private final BackendSession session;
    private final IpcConfirmer confirmer;
    private final IpcFilesClient files;
    private final IpcCodec codec;
    private final Supplier<RuntimeContext> context;
    private final Duration requestTimeout;
    private volatile BackendSession.Status status = new BackendSession.Status(BackendSession.State.CONNECTING, "Not started");
    private volatile boolean closed;
    private Path bulkRoot;

    public IpcUiport(Confirmer frontend, Supplier<RuntimeContext> context) {
        this(frontend,context,Duration.ofSeconds(30));
    }
    public IpcUiport(Confirmer frontend, Supplier<RuntimeContext> context, Duration requestTimeout) {
        this.context = Objects.requireNonNull(context);
        if (requestTimeout == null || requestTimeout.isZero() || requestTimeout.isNegative()) throw new IllegalArgumentException("Positive request timeout required");
        this.requestTimeout = requestTimeout;
        confirmer = new IpcConfirmer(frontend);
        session = new BackendSession(this::enqueueControl, new BackendSession.View() {
            public void statusChanged(BackendSession.Status next) {
                status = next;
                if (next.state() == BackendSession.State.UNAVAILABLE || next.state() == BackendSession.State.DISCONNECTED) {
                    fail(next.state() == BackendSession.State.UNAVAILABLE ? startupFailure(next.detail(),null)
                            : new IpcFailure(IpcFailure.Kind.DISCONNECTED,null,next.detail(),null));
                }
            }
            public void confirmationRequested(String id, ConfirmRequest request, Consumer<String> answer) {
                confirmer.request(id,request,answer,IpcUiport.this::fail);
            }
            public void confirmationFinished(String id, BackendSession.End reason) { confirmer.finish(id); }
            public void confirmationFailed(String id, Throwable error) { fail(error); }
        });
        files = new IpcFilesClient(json,this::release);
        codec = new IpcCodec(json,files);
        session.subscribeEvents(frame -> enqueue(() -> decodeEvent(frame)));
    }

    /** Explicit startup is independent of UI wiring. No in-process fallback is installed. */
    public void start(BackendSession.Command command, Duration handshakeTimeout) {
        session.start(command,handshakeTimeout);
        try { await(session.connected()); }
        catch (IpcFailure e) {
            var problem = startupFailure(e.getMessage(),e);
            fail(problem); throw problem;
        }
        JsonNode response = raw("workspace",json.createObjectNode().put("bulk",true));
        bulkRoot = Path.of(text(response.path("manifest"),"path")).getParent();
        files.root(bulkRoot);
        decode(() -> codec.workspace(files.consumeJson(response.path("manifest"))));
        barrier();
    }
    public BackendSession.Status status() { return status; }
    public CompletableFuture<IpcFailure> failure() { return failure.copy(); }
    public long revision() { return session.revision(); }
    public IpcFilesClient files() { return files; }

    private void enqueue(Runnable work) {
        if (closed) return;
        try { delivery.execute(() -> { deliveryThread = Thread.currentThread(); if (!closed && !failure.isDone()) work.run(); }); }
        catch (RejectedExecutionException e) { if (!closed) fail(e); }
    }
    private void enqueueControl(Runnable work) {
        if (closed) return;
        try { controls.execute(() -> { if (!closed && !failure.isDone()) work.run(); }); }
        catch (RejectedExecutionException e) { if (!closed) fail(e); }
    }
    private CompletableFuture<JsonNode> release(String method, JsonNode params) {
        synchronized (releaseLock) {
            // The frozen server defers releaseFiles while busy. Only one such RPC may be outstanding.
            var next = releaseTail.thenCompose(ignored -> session.request(method,params));
            releaseTail = next;
            next.whenComplete((result,error) -> { if (error != null && !closed) fail(error); });
            return next;
        }
    }
    private CompletableFuture<JsonNode> releases() {
        synchronized (releaseLock) { return releaseTail.copy(); }
    }
    private void decodeEvent(JsonNode frame) {
        try {
            PortEvent event = decode(() -> codec.event(text(frame,"event"),frame.path("data")));
            if (event != null) for (var listener : listeners) listener.accept(event);
        } catch (RuntimeException e) { fail(e); }
    }
    private void fail(Throwable error) {
        IpcFailure problem = classify(error);
        if (failure.complete(problem)) {
            status = new BackendSession.Status(problem.kind() == IpcFailure.Kind.UNAVAILABLE
                    ? BackendSession.State.UNAVAILABLE : BackendSession.State.DISCONNECTED,problem.getMessage());
            files.invalidate(); confirmer.close(); session.close();
        }
    }
    private IpcFailure classify(Throwable e) {
        while ((e instanceof ExecutionException || e instanceof CompletionException) && e.getCause() != null) e = e.getCause();
        if (e instanceof IpcFailure f) return f;
        if (e instanceof BackendSession.RemoteError r) return new IpcFailure(IpcFailure.Kind.REMOTE,r.code(),r.getMessage(),r);
        return new IpcFailure(e instanceof TimeoutException ? IpcFailure.Kind.TIMEOUT : IpcFailure.Kind.PROTOCOL,null,e.getMessage(),e);
    }
    private IpcFailure startupFailure(String detail, Throwable cause) {
        boolean mismatch = detail != null && (detail.contains("mismatch") || detail.contains("required capabilities")
                || detail.contains("Malformed") || detail.contains("Expected backend") || detail.contains("handshake rejected"));
        return new IpcFailure(mismatch ? IpcFailure.Kind.PROTOCOL : IpcFailure.Kind.UNAVAILABLE,null,detail,cause);
    }
    private <T> T await(CompletableFuture<T> future) {
        try { return future.get(requestTimeout.toMillis(),TimeUnit.MILLISECONDS); }
        catch (InterruptedException e) { Thread.currentThread().interrupt(); throw classify(e); }
        catch (ExecutionException | TimeoutException e) { throw classify(e); }
    }
    private void check() {
        if (closed) throw new IpcFailure(IpcFailure.Kind.CLOSED,null,"IPC port closed",null);
        if (failure.isDone()) throw failure.join();
    }
    private JsonNode raw(String method, JsonNode params) {
